  1→//! Remote template source configuration.
  2→//!
  3→//! This module defines types for configuring HTTP and Git-based
  4→//! remote template sources with caching support.
  5→
  6→use serde::{Deserialize, Serialize};
  7→
  8→/// A remote source for templates.
  9→///
 10→/// This enum distinguishes between HTTP/HTTPS URL sources and
 11→/// Git repository sources, each with their own configuration options.
 12→#[derive(Debug, Clone, Deserialize, Serialize)]
 13→#[serde(tag = "type")]
 14→pub enum RemoteSource {
 15→    /// HTTP/HTTPS URL source.
 16→    #[serde(rename = "http")]
 17→    Http {
 18→        /// Base URL for templates.
 19→        url: String,
 20→        /// Cache configuration.
 21→        #[serde(default)]
 22→        cache: RemoteCacheConfig,
 23→    },
 24→    /// Git repository source.
 25→    #[serde(rename = "git")]
 26→    Git {
 27→        /// Repository URL.
 28→        url: String,
 29→        /// Branch or tag to use.
 30→        #[serde(rename = "ref")]
 31→        git_ref: Option<String>,
 32→        /// Path within repository.
 33→        path: Option<String>,
 34→        /// Cache configuration.
 35→        #[serde(default)]
 36→        cache: RemoteCacheConfig,
 37→    },
 38→}
 39→
 40→/// Cache configuration for a remote template source.
 41→#[derive(Debug, Clone, Deserialize, Serialize)]
 42→pub struct RemoteCacheConfig {
 43→    /// Time-to-live in seconds.
 44→    #[serde(default = "default_ttl")]
 45→    pub ttl: u64,
 46→    /// Cache invalidation strategy.
 47→    #[serde(default)]
 48→    pub strategy: RemoteCacheStrategy,
 49→}
 50→
 51→/// Cache invalidation strategy for remote sources.
 52→#[derive(Debug, Clone, Copy, Default, Deserialize, Serialize, PartialEq, Eq)]
 53→#[serde(rename_all = "lowercase")]
 54→pub enum RemoteCacheStrategy {
 55→    /// Use TTL only.
 56→    #[default]
 57→    Ttl,
 58→    /// Use HTTP ETag headers.
 59→    Etag,
 60→    /// Use git commit checking.
 61→    Git,
 62→}
 63→
 64→fn default_ttl() -> u64 {
 65→    604800 // 7 days in seconds
 66→}
 67→
 68→impl Default for RemoteCacheConfig {
 69→    fn default() -> Self {
 70→        Self {
 71→            ttl: default_ttl(),
 72→            strategy: RemoteCacheStrategy::default(),
 73→        }
 74→    }
 75→}
 76→
 77→impl RemoteSource {
 78→    /// Get the cache configuration for this source.
 79→    pub fn cache_config(&self) -> &RemoteCacheConfig {
 80→        match self {
 81→            Self::Http { cache, .. } => cache,
 82→            Self::Git { cache, .. } => cache,
 83→        }
 84→    }
 85→
 86→    /// Get the URL for this source.
 87→    pub fn url(&self) -> &str {
 88→        match self {
 89→            Self::Http { url, .. } => url,
 90→            Self::Git { url, .. } => url,
 91→        }
 92→    }
 93→
 94→    /// Get a unique identifier for this source.
 95→    pub fn id(&self) -> String {
 96→        match self {
 97→            Self::Http { url, .. } => format!("http:{}", url),
 98→            Self::Git { url, git_ref, .. } => {
 99→                format!("git:{}@{}", url, git_ref.as_deref().unwrap_or("HEAD"))
100→            }
101→        }
102→    }
103→}
