//! Cache storage implementation.
//!
//! All writes use atomic temp-file-then-rename to prevent corruption when
//! multiple processes access the cache concurrently. Content is always
//! written before metadata so that metadata acts as the commit point —
//! if we crash after writing content but before metadata, the entry
//! simply doesn't appear (harmless orphan cleaned up on next `clear`).

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use tempfile::NamedTempFile;

use super::entry::CacheEntry;

/// Storage for cached templates.
pub struct CacheStore {
    /// Root directory for cache.
    root: PathBuf,
}

/// Atomically write `data` to `target` by writing to a temp file in the
/// same directory and then renaming. `rename` is atomic on POSIX when
/// source and destination are on the same filesystem.
fn atomic_write(target: &Path, data: &[u8]) -> Result<()> {
    let dir = target
        .parent()
        .with_context(|| format!("Cache path {:?} has no parent directory", target))?;

    let mut tmp = NamedTempFile::new_in(dir)
        .with_context(|| format!("Failed to create temp file in {:?}", dir))?;

    tmp.write_all(data)
        .with_context(|| format!("Failed to write temp file for {:?}", target))?;

    tmp.persist(target)
        .with_context(|| format!("Failed to persist temp file to {:?}", target))?;

    Ok(())
}

impl CacheStore {
    /// Create a new cache store.
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    /// Get the cache root directory.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Ensure the cache directory exists.
    fn ensure_dir(&self) -> Result<()> {
        fs::create_dir_all(&self.root)
            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
    }

    /// Get the path for storing an entry's content.
    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        let key = format!("{}:{}", source_id, template_name);
