/// Atomically write `data` to `target` by writing to a temp file in the
/// same directory and then renaming. `rename` is atomic on POSIX when
/// source and destination are on the same filesystem.
fn atomic_write(target: &Path, data: &[u8]) -> Result<()> {
    let dir = target
        .parent()
        .with_context(|| format!("Cache path {:?} has no parent directory", target))?;

    let mut tmp = NamedTempFile::new_in(dir)
        .with_context(|| format!("Failed to create temp file in {:?}", dir))?;

    tmp.write_all(data)
        .with_context(|| format!("Failed to write temp file for {:?}", target))?;

    tmp.persist(target)
        .with_context(|| format!("Failed to persist temp file to {:?}", target))?;

